// Original Animate UI keyframe values and durations, ported from Motion to WAAPI.
export function animateCatalogueIcon(svg, name, { loop = false } = {}) {
  if (!svg || !svg.animate || matchMedia('(prefers-reduced-motion: reduce)').matches || document.body.classList.contains('motion-paused')) return [];
  const timing = { duration: 600, easing: 'ease-in-out', iterations: loop ? Infinity : 1, delay: loop ? 300 : 0 };
  const animations = [];
  svg.getAnimations({ subtree: true }).forEach(animation => animation.cancel());
  const run = (target, frames, options = {}) => { if(target) animations.push(target.animate(frames, {...timing,...options})); };
  svg.style.transformOrigin = 'center';
  if (name === 'heart') run(svg, [{transform:'scale(1)'},{transform:'scale(.9)'},{transform:'scale(1.2)'},{transform:'scale(1)'}]);
  if (name === 'zap') run(svg, [{transform:'scale(1)'},{transform:'scale(.9)'},{transform:'scale(1.15)'},{transform:'scale(1)'}]);
  if (name === 'sparkles') {
    run(svg,[{transform:'scale(1)'},{transform:'scale(.9)'},{transform:'scale(1.1)'},{transform:'scale(1)'}]);
    const star=svg.querySelector('path:nth-child(2)');
    if(star){star.style.transformBox='fill-box';star.style.transformOrigin='center';run(star,[{transform:'scale(1) rotate(0deg)'},{transform:'scale(.7) rotate(30deg)'},{transform:'scale(1.2) rotate(60deg)'},{transform:'scale(1) rotate(90deg)'}],{delay:150});}
  }
  if (name === 'play') run(svg.querySelector('path'),[{transform:'translateX(0)'},{transform:'translateX(2.5px)'},{transform:'translateX(0)'}]);
  if (name === 'arrow-down-01') run(svg.querySelector('path'),[{transform:'translateY(0)'},{transform:'translateY(4px)'},{transform:'translateY(0)'}]);
  return animations;
}
